hooks.command:
python -c "
import sys, json, shlex, re
data = json.load(sys.stdin)
cmd = data.get('tool_input', {}).get('command', '')
protected = ['meditrack.db', '.env', '.venv']
try:
    tokens = shlex.split(cmd)
except ValueError:
    tokens = cmd.split()
if not tokens:
    sys.exit(0)
destructive = {'rm', 'unlink', 'truncate', 'shred'}
first = tokens[0].split('/')[-1].split('\\')[-1]
if first not in destructive:
    sys.exit(0)
for p in protected:
    if any(p in t for t in tokens[1:]):
        print(f'BLOCKED: Cannot run {first} on protected file: {p}', file=sys.stderr)
        sys.exit(2)
"
